          for (let c = 0; c < nCols; c++) if (tr.grid[c] && tr.grid[c].length) { if (first < 0) first = c; }
          for (let c = nCols - 1; c >= 0; c--) if (tr.grid[c] && tr.grid[c].length) { last = c; break; }
          if (first < 0) { first = 0; last = nCols - 1; }
