  const AUD_EXT = ['mp3', 'wav', 'ogg', 'oga', 'flac', 'm4a', 'aac', 'opus', 'aiff', 'wma'];
  const VID_EXT = ['mp4', 'webm', 'mov', 'mkv', 'avi', 'm4v', 'ogv', 'mpg', 'mpeg', '3gp', 'wmv'];
  const ARC_EXT = ['zip', 'gz', 'tgz', 'tar', '7z', 'rar', 'bz2'];
  const EBK_EXT = ['epub'];
